def transform(grid):
    mask = [(0,0),(1,0),(1,1),(2,2),(3,3),(4,3)]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h-4):
        for c in range(w-3):
            if all(grid[r+dr][c+dc] == 0 for dr,dc in mask):
                for dr,dc in mask: out[r+dr][c+dc] = 7
    return out
